package android.app.job; import java.util.ArrayList;import java.util.List;public class JobService extends android.content.Context {public final List<JobParameters> completed=new ArrayList<>();public final List<Boolean> retry=new ArrayList<>();public boolean onStartJob(JobParameters p){return false;}public boolean onStopJob(JobParameters p){return false;}public void onDestroy(){}public void jobFinished(JobParameters p,boolean reschedule){completed.add(p);retry.add(reschedule);}}
